children.summary:
找連通塊、判斷是否有環（如 207 題）等。部分題目**做法不止一種**。

模板（計算每個連通塊的大小）：

```py [sol-Python3]
def solve(n: int, edges: list[list[int]]) -> list[int]:
    # 節點編號從 0 到 n-1
    g = [[] for _ in range(n)]
    for x, y in edges:
        g[x].append(y)
        g[y].append(x)  # 無向圖

    vis = [False] * n

    def dfs(x: int) -> int:
        vis[x] = True  # 避免重複訪問節點
        size = 1
        for y in g[x]:
            if not vis[y]:
                size += dfs(y)
        return size

    # 計算每個連通塊的大小
    ans = []
    for i, b in enumerate(vis):
        if not b:  # i 沒有訪問過
            size = dfs(i)
            ans.append(size)
    return ans
```

```java [sol-Java]
class Solution {
    public List<Integer> solve(int n, int[][] edges) {
        // 節點編號從 0 到 n-1
        List<Integer>[] g = new ArrayList[n];
        Arrays.setAll(g, _ -> new ArrayList<>());
        for (int[] e : edges) {
            int x = e[0];
            int y = e[1];
            g[x].add(y);
            g[y].add(x); // 無向圖
        }

        // 計算每個連通塊的大小
        List<Integer> ans = new ArrayList<>();
        boolean[] vis = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (!vis[i]) { // i 沒有訪問過
                int size = dfs(i, vis, g);
                ans.add(size);
            }
        }
        return ans;
    }

    private int dfs(int x, boolean[] vis, List<Integer>[] g) {
        vis[x] = true; // 避免重複訪問節點
        int size = 1;
        for (int y : g[x]) {
            if (!vis[y]) {
                size += dfs(y, vis, g);
            }
        }
        return size;
    }
}
```

