求最短路等。要求邊權都是 $1$（或者說都是同一個正數）。

模板（單源最短路）：

```py [sol-Python3]
# 計算從 start 到各個節點的最短路長度
# 如果節點不可達，則最短路長度為 -1
# 節點編號從 0 到 n-1，邊權均為 1
def bfs(n: int, edges: list[list[int]], start: int) -> list[int]:
    g = [[] for _ in range(n)]
    for x, y in edges:
        g[x].append(y)
        g[y].append(x)  # 無向圖

    dis = [-1] * n  # -1 表示尚未訪問到
    dis[start] = 0
    q = deque([start])
    while q:
        x = q.popleft()
        for y in g[x]:
            if dis[y] < 0:
                dis[y] = dis[x] + 1
                q.append(y)
    return dis
```

```java [sol-Java]
class Solution {
    // 計算從 start 到各個節點的最短路長度
    // 如果節點不可達，則最短路長度為 -1
    // 節點編號從 0 到 n-1，邊權均為 1
    public int[] bfs(int n, int[][] edges, int start) {
        List<Integer>[] g = new ArrayList[n];
        Arrays.setAll(g, _ -> new ArrayList<>());
        for (int[] e : edges) {
            int x = e[0], y = e[1];
            g[x].add(y);
            g[y].add(x); // 無向圖
        }

        int[] dis = new int[n];
        Arrays.fill(dis, -1); // -1 表示尚未訪問到
        Queue<Integer> q = new ArrayDeque<>();
        dis[start] = 0;
        q.offer(start);
        while (!q.isEmpty()) {
            int x = q.poll();
            for (int y : g[x]) {
                if (dis[y] < 0) {
                    dis[y] = dis[x] + 1;
                    q.offer(y);
                }
            }
        }
        return dis;
    }
}
