// 計算從 start 到各個節點的最短路長度
// 如果節點不可達，則最短路長度為 -1
// 節點編號從 0 到 n-1，邊權均為 1
func bfs(n int, edges [][]int, start int) []int {
	g := make([][]int, n)
	for _, e := range edges {
		x, y := e[0], e[1]
		g[x] = append(g[x], y)
		g[y] = append(g[y], x) // 無向圖
	}

	dis := make([]int, n)
	for i := range dis {
		dis[i] = -1 // -1 表示尚未訪問到
	}
	dis[start] = 0
	q := []int{start}
	for len(q) > 0 {
		x := q[0]
		q = q[1:]
		for _, y := range g[x] {
			if dis[y] < 0 {
				dis[y] = dis[x] + 1
				q = append(q, y)
			}
		}
	}
	return dis
}
