```go [sol-Go]
// 返回有向無環圖（DAG）的其中一個拓撲序
// 如果圖中有環，返回 nil
// 節點編號從 0 到 n-1
func topologicalSort(n int, edges [][]int) []int {
	g := make([][]int, n)
	inDeg := make([]int, n)
	for _, e := range edges {
		x, y := e[0], e[1]
		g[x] = append(g[x], y)
		inDeg[y]++ // 統計 y 的先修課數量
	}

	q := make([]int, 0, n)
	topoOrder := q
	for i, d := range inDeg {
		if d == 0 { // 沒有先修課，可以直接上
			q = append(q, i) // 加入學習佇列
		}
	}
	for len(q) > 0 {
		x := q[0]
		q = q[1:]
		for _, y := range g[x] {
			inDeg[y]-- // 修完 x 後， y 的先修課數量減一
			if inDeg[y] == 0 { // y 的先修課全部上完
				q = append(q, y) // 加入學習佇列
			}
		}
	}

	if cap(q) > 0 { // 圖中有環
		return nil
	}
	return topoOrder[:n]
}
