[Dijkstra 演算法介紹](https://leetcode.cn/problems/network-delay-time/solution/liang-chong-dijkstra-xie-fa-fu-ti-dan-py-ooe8/)

模板：

```py [sol-Python3]
# 返回從起點 start 到每個點的最短路長度 dis，如果節點 x 不可達，則 dis[x] = math.inf
# 要求：沒有負數邊權
# 時間複雜度 O(n + mlogm)，其中 m 是 edges 的長度。注意堆中有 O(m) 個元素
def shortestPathDijkstra(n: int, edges: list[list[int]], start: int) -> list[int]:
    # 注：如果節點編號從 1 開始（而不是從 0 開始），可以把 n 加一
    g = [[] for _ in range(n)]  # 鄰接表
    for x, y, wt in edges:
        g[x].append((y, wt))
        # g[y].append((x, wt))  # 無向圖加上這行

    dis = [math.inf] * n
    dis[start] = 0  # 起點到自己的距離是 0
    h = [(0, start)]  # 堆中儲存 (起點到節點 x 的最短路長度，節點 x)

    while h:
        dis_x, x = heappop(h)
        if dis_x > dis[x]:  # x 之前出堆過
            continue
        for y, wt in g[x]:
            new_dis_y = dis_x + wt
            if new_dis_y < dis[y]:
                dis[y] = new_dis_y  # 更新 x 的鄰居的最短路
                # 懶更新堆：只插入資料，不更新堆中資料
                # 相同節點可能有多個不同的 new_dis_y，除了最小的 new_dis_y，其餘值都會觸發上面的 continue
                heappush(h, (new_dis_y, y))

    return dis
```

```java [sol-Java]
class Solution {
    // 返回從起點 start 到每個點的最短路長度 dis，如果節點 x 不可達，則 dis[x] = Integer.MAX_VALUE
    // 要求：沒有負數邊權
    // 時間複雜度 O(n + mlogm)，注意堆中有 O(m) 個元素
    private int[] shortestPathDijkstra(int n, int[][] edges, int start) {
        // 注：如果節點編號從 1 開始（而不是從 0 開始），可以把 n 加一
        List<int[]>[] g = new ArrayList[n]; // 鄰接表
        Arrays.setAll(g, _ -> new ArrayList<>());
        for (int[] e : edges) {
            int x = e[0];
            int y = e[1];
            int wt = e[2];
            g[x].add(new int[]{y, wt});
            // g[y].add(new int[]{x, wt}); // 無向圖加上這行
        }

        int[] dis = new int[n]; // **如果資料範圍大，改成 long[]**
        Arrays.fill(dis, Integer.MAX_VALUE);
        // 堆中儲存 (起點到節點 x 的最短路長度，節點 x)
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        dis[start] = 0; // 起點到自己的距離是 0
        pq.offer(new int[]{0, start});

        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int disX = top[0];
            int x = top[1];
            if (disX > dis[x]) { // x 之前出堆過
                continue;
            }
            for (int[] e : g[x]) {
                int y = e[0];
                int wt = e[1];
                int newDisY = disX + wt;
                if (newDisY < dis[y]) {
                    dis[y] = newDisY; // 更新 x 的鄰居的最短路
                    // 懶更新堆：只插入資料，不更新堆中資料
                    // 相同節點可能有多個不同的 newDisY，除了最小的 newDisY，其餘值都會觸發上面的 continue
                    pq.offer(new int[]{newDisY, y});
                }
            }
        }

        return dis;
    }
}
