```cpp [sol-C++]
// 返回從起點 start 到每個點的最短路長度 dis，如果節點 x 不可達，則 dis[x] = LLONG_MAX
// 要求：沒有負數邊權
// 時間複雜度 O(n + mlogm)，注意堆中有 O(m) 個元素
vector<long long> shortestPathDijkstra(int n, vector<vector<int>>& edges, int start) {
    // 注：如果節點編號從 1 開始（而不是從 0 開始），可以把 n 加一
    vector<vector<pair<int, int>>> g(n); // 鄰接表
    for (auto& e : edges) {
        int x = e[0], y = e[1], wt = e[2];
        g[x].emplace_back(y, wt);
        // g[y].emplace_back(x, wt); // 無向圖加上這行
    }

    vector<long long> dis(n, LLONG_MAX);
    // 堆中儲存 (起點到節點 x 的最短路長度，節點 x)
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;
    dis[start] = 0; // 起點到自己的距離是 0
    pq.emplace(0, start);

    while (!pq.empty()) {
        auto [dis_x, x] = pq.top();
        pq.pop();
        if (dis_x > dis[x]) { // x 之前出堆過
            continue;
        }
        for (auto& [y, wt] : g[x]) {
            auto new_dis_y = dis_x + wt;
            if (new_dis_y < dis[y]) {
                dis[y] = new_dis_y; // 更新 x 的鄰居的最短路
                // 懶更新堆：只插入資料，不更新堆中資料
                // 相同節點可能有多個不同的 new_dis_y，除了最小的 new_dis_y，其餘值都會觸發上面的 continue
                pq.emplace(new_dis_y, y);
            }
        }
    }

    return dis;
}
