// 返回從起點 start 到每個點的最短路長度 dis，如果節點 x 不可達，則 dis[x] = math.MaxInt
// 要求：沒有負數邊權
// 時間複雜度 O(n + mlogm)，注意堆中有 O(m) 個元素
func shortestPathDijkstra(n int, edges [][]int, start int) []int {
    // 注：如果節點編號從 1 開始（而不是從 0 開始），可以把 n 加一
    type edge struct{ to, wt int }
    g := make([][]edge, n) // 鄰接表
    for _, e := range edges {
        x, y, wt := e[0], e[1], e[2]
        g[x] = append(g[x], edge{y, wt})
        // g[y] = append(g[y], edge{x, wt}) // 無向圖加上這行
    }

    dis := make([]int, n)
    for i := range dis {
        dis[i] = math.MaxInt
    }
    dis[start] = 0 // 起點到自己的距離是 0
    // 堆中儲存 (起點到節點 x 的最短路長度，節點 x)
    h := &hp{{0, start}}

    for h.Len() > 0 {
        p := heap.Pop(h).(pair)
        disX, x := p.dis, p.x
        if disX > dis[x] { // x 之前出堆過
            continue
        }
        for _, e := range g[x] {
            y := e.to
            newDisY := disX + e.wt
            if newDisY < dis[y] {
                dis[y] = newDisY // 更新 x 的鄰居的最短路
                // 懶更新堆：只插入資料，不更新堆中資料
                // 相同節點可能有多個不同的 newDisY，除了最小的 newDisY，其餘值都會觸發上面的 continue
                heap.Push(h, pair{newDisY, y})
            }
        }
    }

    return dis
}

type pair struct{ dis, x int }
type hp []pair

func (h hp) Len() int           { return len(h) }
func (h hp) Less(i, j int) bool { return h[i].dis < h[j].dis }
func (h hp) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *hp) Push(v any)        { *h = append(*h, v.(pair)) }
func (h *hp) Pop() (v any)      { a := *h; *h, v = a[:len(a)-1], a[len(a)-1]; return }
