    // 如果計算完畢後，存在 i，使得從 i 到 i 的最短路長度小於 0，說明圖中有負環
    // 節點編號從 0 到 n-1
    // 時間複雜度 O(n^3 + m)，其中 m 是 edges 的長度
    public long[][] shortestPathFloyd(int n, int[][] edges) {
        final long INF = Long.MAX_VALUE / 2; // 防止加法溢位
        long[][] f = new long[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(f[i], INF);
            f[i][i] = 0;
        }

        for (int[] e : edges) {
            int x = e[0];
            int y = e[1];
            int wt = e[2];
            f[x][y] = Math.min(f[x][y], wt); // 如果有重邊，取邊權最小值
            f[y][x] = Math.min(f[y][x], wt); // 無向圖
        }

        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                if (f[i][k] == INF) { // 針對稀疏圖的最佳化
                    continue;
                }
                for (int j = 0; j < n; j++) {
                    f[i][j] = Math.min(f[i][j], f[i][k] + f[k][j]);
                }
            }
        }
        return f;
    }
}
