// 節點編號從 0 到 n-1
// 時間複雜度 O(n^3 + m)，其中 m 是 edges 的長度
func shortestPathFloyd(n int, edges [][]int) [][]int {
	const inf = math.MaxInt / 2 // 防止加法溢位
	f := make([][]int, n)
	for i := range f {
		f[i] = make([]int, n)
		for j := range f[i] {
			f[i][j] = inf
		}
		f[i][i] = 0
	}

	for _, e := range edges {
		x, y, wt := e[0], e[1], e[2]
		f[x][y] = min(f[x][y], wt) // 如果有重邊，取邊權最小值
		f[y][x] = min(f[y][x], wt) // 無向圖
	}

	for k := range n {
		for i := range n {
			if f[i][k] == inf { // 針對稀疏圖的最佳化
				continue
			}
			for j := range n {
				f[i][j] = min(f[i][j], f[i][k]+f[k][j])
			}
		}
	}
	return f
}
