}

func newUnionFind(n int) unionFind {
	fa := make([]int, n)
	// 一開始有 n 個集合 {0}, {1}, ..., {n-1}
	// 集合 i 的代表元是自己
	for i := range fa {
		fa[i] = i
	}
	return unionFind{fa, n}
}

// 返回 x 所在集合的代表元
// 同時做路徑壓縮，也就是把 x 所在集合中的所有元素的 fa 都改成代表元
func (u unionFind) find(x int) int {
	// 如果 fa[x] == x，則表示 x 是代表元
	if u.fa[x] != x {
		u.fa[x] = u.find(u.fa[x]) // fa 改成代表元
	}
	return u.fa[x]
}

// 把 from 所在集合合併到 to 所在集合中
// 返回是否合併成功
func (u *unionFind) merge(from, to int) bool {
	x, y := u.find(from), u.find(to)
	if x == y { // from 和 to 在同一個集合，不做合併
		return false
	}
	u.fa[x] = y // 合併集合。修改後就可以認為 from 和 to 在同一個集合了
	u.cc--      // 成功合併，連通塊個數減一
	return true
}

// 計算圖的最小生成樹的邊權之和
// 如果圖不連通，返回 math.MaxInt
// 節點編號從 0 到 n-1
// 時間複雜度 O(n + mlogm)，其中 m 是 edges 的長度
func mstKruskal(n int, edges [][]int) int {
	slices.SortFunc(edges, func(a, b []int) int { return a[2] - b[2] })

	uf := newUnionFind(n)
	sumWt := 0
	for _, e := range edges {
		x, y, wt := e[0], e[1], e[2]
		if uf.merge(x, y) {
			sumWt += wt
		}
	}

	if uf.cc > 1 { // 圖不連通
		return math.MaxInt
	}
	return sumWt
}
