    private int[] colorBipartite(int n, int[][] edges) {
        // 建圖（節點編號從 0 到 n-1）
        List<Integer>[] g = new ArrayList[n];
        Arrays.setAll(g, _ -> new ArrayList<>());
        for (int[] e : edges) {
            int x = e[0], y = e[1];
            g[x].add(y);
            g[y].add(x);
        }

        // colors[i] = 0 表示未訪問節點 i
        // colors[i] = 1 表示節點 i 為紅色
        // colors[i] = 2 表示節點 i 為藍色
        int[] colors = new int[n];

        for (int i = 0; i < n; i++) {
            if (colors[i] == 0 && !dfs(i, 1, g, colors)) {
                // 從節點 i 開始遞迴，發現 i 所在連通塊不是二分圖
                return new int[]{};
            }
        }
        return colors;
    }

    private boolean dfs(int x, int c, List<Integer>[] g, int[] colors) {
        colors[x] = c; // 節點 x 染成顏色 c
        for (int y : g[x]) {
            // 鄰居 y 的顏色與 x 的相同，說明不是二分圖，返回 false
            // 或者繼續遞迴，發現不是二分圖，返回 false
            if (colors[y] == c || 
                colors[y] == 0 && !dfs(y, 3 - c, g, colors)) { // 1 和 2 交替染色
                return false;
            }
        }
        return true;
    }
